"""Publish the reviewed operator flow, preserving prior progress history bytes."""
import hashlib,json,re,datetime as dt
from manual_grasp_plan_20261106 import R,OUT,REQUEST,PROOF,ManualGraspPlan,sha,validate_candidate
from manual_grasp_gate_20261106 import validate_review
def main():
    plan=ManualGraspPlan(REQUEST);review=validate_review(plan,PROOF);rows=plan.plan(plan.source_position());z=validate_candidate();tests=R/'manual_grasp_tests_20261106.log';log=tests.read_text(encoding='utf-8');count=int(re.search(r'Ran (\d+) tests',log).group(1));assert count==11 and log.rstrip().endswith('OK')
    reader=max(OUT.glob('reader_check_*.json'),key=lambda p:p.stat().st_mtime);r=json.loads(reader.read_bytes());assert r['status']=='OFF_teaching_reader_verified' and len(r['snapshots'])==2 and r['servo_writes']==r['torque_changes']==0 and set(r['instruction_counts'])<={'1','2','138'}
    for state in r['snapshots']:assert not any(state['torque']) and not any(state['error']) and not any(state['watchdog'])
    guide='''# 손가락 각도 보정 실행\n\n실행 파일: `leap_manual_grasp_teach.cmd`\n\n방금 실행한 자연 홈 파지의 같은 목표까지만 진행한다. 자동 열기와 회전은 없다. 진행 숫자는 현재 빈손 자세에 따라 달라지므로1710이라는 숫자 대신 프로그램의 단계 문구를 따른다.\n\n1. 큐브를 손과 카메라 밖에 두고 첫SPACE. 현재 빈손 자세를 읽고 준비 자세로 이동한다.\n2. PLACE가 뜨면 초록 위, 주황 손목ID41 쪽으로 자연스럽게 놓는다. 손을 뗀 뒤 두 번째SPACE로 같은 파지까지 이동한다.\n3. `[파지 완료 / 자동 열기 없음]`에서 큐브를 아래에서 받치고 세 번째SPACE. 이때는 손가락 각도를 아직 바꾸지 않는다.\n4. `[토크OFF 보정]`이 나타나면 원하는 손가락 각도만 천천히 바꾼다. 큐브는 같은 곳에서 받치고,5V 전원과USB는 연결한 채 둔다. 모터 힘만 꺼져 있다.\n5. 보정한 모양을 유지하면서 네 번째SPACE. 새 사진 앞뒤로 관절값을 읽고, 각도가 움직였으면 다시 저장을 안내한다.\n\n저장 뒤에도 모터 힘은OFF다. 자동으로 다시 켜지지 않는다. 새 각도는 먼저 모델에서 검토하므로 모터 프로그램이나 위자드에서 토크를 따로 켜지 않는다. 새 목표를 미리 넣지 않으면 보정 전 목표로 돌아가려 할 수 있다.\n\n저장 위치는 `manual_grasp_teach_날짜_시간` 폴더와 `leap_manual_grasp_teach_result.json`이다. 완성되면 채팅에 했어라고 알려주면 된다. 로그를 복사할 필요는 없다. 사람이 받친 상태와 모터OFF 때의 처짐을 포함한 자료이며 자동 파지 성공이나SAC 학습 완료로 표시하지 않는다.\n'''
    (OUT/'operator_guide.md').write_text(guide,encoding='utf-8')
    result=dict(status='ready_for_user_started_manual_joint_teaching',created_utc=dt.datetime.now(dt.timezone.utc).isoformat(),entrypoint='leap_manual_grasp_teach.cmd',review_sha256=sha(PROOF),candidate_sha256=sha(OUT/'candidate.npz'),loaded_goal_count=len(z['goals']),whole_goal_count=len(rows),nominal_motion_seconds=len(rows)*.075,automatic_open=False,new_joint_goal_vectors=0,manual_joint_changes_only_after_verified_OFF=True,automatic_reenable=False,software_tests=count,tests_log_sha256=sha(tests),reader_test=reader.relative_to(R).as_posix(),reader_test_sha256=sha(reader),prefix_static_model_cases=len(review['empty_recovery']['static_cases']),prefix_dynamic_model_cases=len(review['empty_recovery']['dynamic_cases']),motion_not_executed_by_assistant=True,manual_corrected_pose_not_yet_recorded=True,code_hashes=review['code_hashes'],current_servo_writes_by_assistant=0)
    progress=R/'professor_progress_20261015.md';data=progress.read_bytes();begin=b'<!-- manual_grasp_teach_20261106_current -->';end=b'<!-- manual_grasp_teach_20261106_end -->'
    if data.startswith(begin):data=data.split(end,1)[1].lstrip(b'\r\n')
    result['preserved_prior_progress_sha256']=hashlib.sha256(data).hexdigest()
    header='''<!-- manual_grasp_teach_20261106_current -->\n## CURRENT 2026-11-06: 손가락 각도 수동 보정 준비\n\n- 사용자는 큐브 위치가 아니라 이전 파지 관찰 자세에서 손가락 각도를 직접 바꾸려 한다. 모터ON 상태에서 밀어 바꾸도록 하지 않는다.\n- `leap_manual_grasp_teach.cmd`: 빈손 첫SPACE → PLACE와 두 번째SPACE → 이전 파지 → 큐브 받치고 세 번째SPACE OFF → 토크OFF 확인 후 손가락 보정 → 네 번째SPACE로 사진/각도 저장. 자동 열기와 자동 재구동은 없다.\n- 기존 자연 홈 파지의927목표만 그대로 유지했다. 새 각도 목표는 추가하지 않았다. 현재 빈손 기준 전체1470목표,110.25초다.1710이라는 진행 숫자는 시작 자세에 따라 달라진다.\n- 현재 복귀의 정적201조건 및 동적9조건, 새 소프트웨어 시험11개를 통과했다. 실제 읽기 전용 검사에서16PING,16READ,8FastREAD로 두 상태를 확보했고 토크/설정 쓰기는0이었다.\n- 방금 실물 실행 원본: `natural_cradle_grasp_20261106_175553_695333`. 토크OFF와 설정 복구, 큐브 제거는 확인됐다. 엄지 패드가 윗단 가까이 닿는 사진을 확인했다.\n- 새 보정 동작은 사용자가 아직 실행하지 않았다. 다음에는 `manual_grasp_teach_*`의 결과를 읽고, 보정한 각도와사진을 확인한 뒤 원래 관절/충돌 기준으로 검토한다. 저장 각도를 즉시토크ON으로 실행하지 않는다.\n- 안내와 출처: `right_hand_rotation_20261106/manual_grasp/operator_guide.md` 및 `ready.json`. 이전 오프라인 모델 결과는 아래에 보존한다.\n\n<!-- manual_grasp_teach_20261106_end -->\n\n'''.replace('\n','\r\n').encode('utf-8');progress.write_bytes(header+data)
    assert progress.read_bytes().split(end,1)[1].lstrip(b'\r\n')==data
    (OUT/'ready.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({k:v for k,v in result.items() if k!='code_hashes'}),flush=True)
if __name__=='__main__':main()
